		v1:GiveTask(function() --[[ Line: 23 | Upvalues: v12 (ref) ]]
			v12:cancel()
			v12 = nil
		end)
	end))
	v1:GiveTask(p1.AncestryChanged:Connect(function() --[[ Line: 29 | Upvalues: p1 (copy), v1 (copy) ]]
		if p1:IsDescendantOf(game) then
