local function getRarityLuckMultiplier(p1, p2) --[[ getRarityLuckMultiplier | Line: 686 | Upvalues: ItemRarity (copy) ]]
	local v1 = p2 or 0
	if p1 == ItemRarity.Common then
		return math.max(0.1, 1 - 0.25 * v1)
	end
	if p1 == ItemRarity.Uncommon then
		return 1 + 0.1 * v1
	end
	if p1 == ItemRarity.Rare then
		return 1 + 0.2 * v1
	end
	if p1 == ItemRarity.UltraRare then
		return 1 + 0.35 * v1
	end
	if p1 == ItemRarity.Legendary then
		return 1 + 0.5 * v1
	end
	if p1 == ItemRarity.Collectible then
		return 1 + 0.75 * v1
	else
		return 1
	end
end
local function getAdjustedDropRates(p1, p2) --[[ getAdjustedDropRates | Line: 706 | Upvalues: getRarityLuckMultiplier (copy) ]]
	local tbl = {}
	local sum = 0
	for k, v in pairs(p1.DropList) do
		local v1 = v.Chance * getRarityLuckMultiplier(k, p2)
		tbl[k] = v1
		sum = sum + v1
	end
	for k, v in pairs(tbl) do
		tbl[k] = v / sum
	end
	return tbl
end
