				end
				if v:IsA("MeshPart") and Neon then
					v.TextureID = ""
				end
				if v:IsA("BasePart") then
					if Neon then
						v.Material = Neon
					end
					tweenColor(v)
				end
				if v:IsA("Shirt") or (v:IsA("Pants") or v:IsA("Decal")) then
					v:Destroy()
				end
