	Gamepad.Stab.ButtonIcon.Image = UserInputService:GetImageForKeyCode(Enum.KeyCode.ButtonR2)
	Gamepad_2.Shoot.ButtonIcon.Image = UserInputService:GetImageForKeyCode(Enum.KeyCode.ButtonR2)
	for i, v in ipairs(t) do
		v.Visible = UserInputService.GamepadEnabled
	end
	for i, v in ipairs(t2) do
		v.Visible = UserInputService.KeyboardEnabled and not UserInputService.GamepadEnabled
	end
end
onGamepadEvent()
UserInputService.GamepadConnected:Connect(onGamepadEvent)
UserInputService.GamepadDisconnected:Connect(onGamepadEvent)
local tbl = {
	[Tags.KNIFE_TOOL] = KnifeControls,
	[Tags.GUN_TOOL] = GunControls
}
for k, v in pairs(tbl) do
